function createBuffer(channels,rate){const b=new AudioBuffer({numberOfChannels:channels.length,length:channels[0].length,sampleRate:rate});channels.forEach((d,c)=>b.copyToChannel(d,c));return b;}
function generateDemo(key){const rate=32000,n=rate*8,channels=[new Float32Array(n),new Float32Array(n)];let seed=721;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};const notes=[130.8128,164.8138,195.9977,261.6256,329.6276,391.9954,523.2511,659.2551];let noise=0;for(let i=0;i<n;i++){const t=i/rate;let v=0;if(key==='glass'||key==='piano'){for(let j=0;j<8;j++){const age=t-j*.78-.15;if(age>=0&&age<4){const f=notes[j];if(key==='glass')v+=(Math.sin(t*f*2*Math.PI)+.4*Math.sin(t*f*2.76*2*Math.PI)+.2*Math.sin(t*f*5.4*2*Math.PI))*Math.exp(-age*2.3)*Math.min(1,age*180)*.24;else v+=(Math.sin(t*f*2*Math.PI)+.35*Math.sin(t*f*4*Math.PI)+.14*Math.sin(t*f*6*Math.PI))*Math.exp(-age*1.8)*Math.min(1,age*90)*.25;}}}else if(key==='rain'){noise=noise*.94+(rnd()*2-1)*.06;v=noise*.9+(rnd()<.001?(rnd()-.5)*.8:0);v+=Math.sin(t*87*2*Math.PI)*.06*Math.sin(t*.8)**2;}else{const f=110+Math.sin(t*.7)*3;const formant=600+600*(.5+.5*Math.sin(t*.8));for(let h=1;h<32;h++){const weight=Math.exp(-(((h*f-formant)/300)**2))+.25*Math.exp(-(((h*f-2300)/450)**2));v+=Math.sin(t*f*h*2*Math.PI)*weight*.06;}v*=Math.min(1,t*4,Math.max(0,(8-t)*2));}channels[0][i]=v;channels[1][i]=v*.92+Math.sin(t*261.6256*2*Math.PI)*.008;}return createBuffer(channels,rate);}
