function applyPreset(key){const presets={cloud:{size:900,density:26,spray:35,speed:.08,pitch:-12,reverse:25,static:10,jump:0,hold:0,elastic:0,chaos:0,reverb:60,delayMix:12,tapeOn:false,cutoff:6500},shards:{size:70,density:28,spray:75,speed:.65,pitch:12,reverse:35,static:0,jump:35,hold:8,elastic:12,chaos:35,reverb:24,delayMix:30,tapeOn:false,cutoff:16000},worn:{size:480,density:15,spray:18,speed:.15,pitch:-5,reverse:8,static:25,jump:0,hold:0,elastic:2,chaos:10,reverb:38,delayMix:23,tapeOn:true,drive:55,wow:65,flutter:35,hiss:22,cutoff:4000}};Object.assign(params,presets[key]);params.freeze=false;params.scanOn=true;refreshControls();showTab('grain');toast({cloud:'Slow cloud · long grains and a wide space.',shards:'Glass shards · short grains, scattered and bright.',worn:'Worn memory · warm tape with gentle instability.'}[key]);}
$('playBtn').onclick=togglePlay;$('testSound').onclick=testSound;$('restartAudio').onclick=restartAudio;$('freezeBtn').onclick=toggleFreeze;$('scanToggle').onclick=()=>{params.scanOn=!params.scanOn;refreshControls();};$('tapeToggle').onclick=()=>{params.tapeOn=!params.tapeOn;refreshControls();};$('scanMode').onchange=()=>{params.scanMode=$('scanMode').value;syncEngine();};$('filterType').onchange=syncEngine;$('volume').oninput=()=>{if(master)master.gain.setTargetAtTime(+$('volume').value,ctx.currentTime,.03);};$('demo').onchange=()=>{loadDemo($('demo').value);};$('importBtn').onclick=()=>$('audioFile').click();$('audioFile').onchange=e=>{if(e.target.files[0])importAudio(e.target.files[0]);e.target.value='';};$('micBtn').onclick=toggleMic;$('applyTrim').onclick=applyTrim;$('resetSample').onclick=()=>{if(originalBuffer){setSample(originalBuffer,sourceName,'RESTORED AUDIO',true);toast('Full original sample restored.');}};$('previewSource').onclick=async()=>{try{await ensureAudio();if(previewNode){previewNode.stop();previewNode=null;$('previewSource').textContent='▷ Listen to source';return;}previewNode=ctx.createBufferSource();previewNode.buffer=buffer;previewNode.connect(master);previewNode.onended=()=>{previewNode=null;$('previewSource').textContent='▷ Listen to source';};previewNode.start();$('previewSource').textContent='■ Stop source';}catch(e){toast(e.message);}};$('saveProject').onclick=saveProject;$('loadProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=e=>{if(e.target.files[0])loadProject(e.target.files[0]);e.target.value='';};$('recordOut').onclick=toggleCapture;$('aboutBtn').onclick=()=>$('about').showModal();$('closeAbout').onclick=()=>$('about').close();$('about').addEventListener('click',e=>{if(e.target===$('about')){const r=$('about').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('about').close();}});
window.addEventListener('hushfield:pagechange',event=>showTab(event.detail));document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));$('resetBalls').onclick=resetBalls;$('orbitShape').onchange=()=>{containBalls(orbitState,orbitOptions());updateOrbitReadout();};$('addPoint').onclick=()=>changePoints(1);$('removePoint').onclick=()=>changePoints(-1);$('reverseSpin').onclick=()=>{params.orbitSpin=-params.orbitSpin;refreshControls();};$('stopSpin').onclick=()=>{params.orbitSpin=0;refreshControls();};$('orbitKey').value='C';$('orbitCanvas').addEventListener('pointerdown',()=>{for(const b of balls){b.vx+=(Math.random()-.5)*1.5;b.vy-=1;}toast('A little nudge.');});$('randomize').onclick=()=>{Object.assign(params,{spray:Math.round(Math.random()*75),size:Math.round(60+Math.random()*800),density:Math.round(8+Math.random()*35),reverse:Math.round(Math.random()*70),jump:Math.round(Math.random()*30),elastic:Math.round(Math.random()*15),chaos:Math.round(Math.random()*40)});refreshControls();toast('A new grain texture.');};
let draggingWave=false;function wavePosition(e){const r=$('waveform').getBoundingClientRect();params.position=clamp((e.clientX-r.left)/r.width*100,0,100);ranges.position.input.value=params.position;ranges.position.render();stats.scan=params.position/100;syncEngine();}$('waveform').addEventListener('pointerdown',e=>{draggingWave=true;$('waveform').setPointerCapture(e.pointerId);wavePosition(e);});$('waveform').addEventListener('pointermove',e=>{if(draggingWave)wavePosition(e);});$('waveform').addEventListener('pointerup',()=>draggingWave=false);$('waveform').addEventListener('pointercancel',()=>draggingWave=false);
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA','BUTTON','A'].includes(e.target.tagName)||$('about').open)return;if(e.code==='Space'){e.preventDefault();togglePlay();}if(e.code==='KeyF'){e.preventDefault();toggleFreeze();}});document.addEventListener('dragover',e=>{e.preventDefault();document.body.classList.add('dragging');});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('dragging');});document.addEventListener('drop',e=>{e.preventDefault();document.body.classList.remove('dragging');const f=e.dataTransfer.files[0];if(f){if(f.name.endsWith('.json'))loadProject(f);else importAudio(f);}});window.addEventListener('beforeunload',e=>{if(micRecording||outputRecording){e.preventDefault();e.returnValue='';}micStream?.getTracks().forEach(t=>t.stop());});

function setupDisplay(){
 const stage=document.createElement('div');stage.id='displayStage';$('waveWrap').before(stage);stage.append($('waveWrap'),document.querySelector('.orbit-stage'));
 const deck=document.createElement('div');deck.id='tapeDeck';deck.innerHTML='<canvas id="tapeCanvas" aria-label="Animated tape cassette with rotating reels and tape path"></canvas>';stage.append(deck);const ambient=document.createElement('div');ambient.id='ambientStage';ambient.innerHTML='<canvas id="ambientCanvas" aria-label="Ambient landscape. Drag the four voice dots to change pitch and stereo position."></canvas><div class="ambient-readout"><strong id="ambientSceneName">Stillwater</strong><span id="ambientHarmony">C minor / Cm7</span></div><div class="ambient-time"><span id="ambientElapsed">00:00</span><span id="ambientNext">NEXT CHORD 48 s</span></div>';stage.append(ambient);
 const visual=document.createElement('div');visual.id='visualStage';visual.append($('visualCanvas'),document.querySelector('.visual-caption'));stage.append(visual);
 const utility=document.createElement('div');utility.className='utility-strip';document.querySelector('.main-panel').after(utility);utility.append($('freezeBtn'),$('recordOut'),document.querySelector('.volume-label'),document.querySelector('.meter'));
 for(const id of ['delayMix','feedback','delayTime'])$('tapeControls').prepend(document.querySelector(`[data-control="${id}"]`));
 // Echo controls live on Tape; FX keeps a direct route to the same bus.
 $('delayControls').innerHTML='<p class="fx-tape-copy">Magnetic repeats on the master bus.</p><button class="large-action" id="openTape">Edit tape echo</button>';$('openTape').onclick=()=>showTab('tape');
}
setupDisplay();
