soundEditors=setupSoundEditors({getState:()=>soundState,getCount:bank=>bank==='triggers'?params.orbitTriggers:params.orbitBalls,onChange:changeSound,onReset:(bank,index)=>{resetSound(soundState,bank,index);orbitAudio?.stop(bank,index==='all'?undefined:index);orbitAudio?.sync(soundState);updatePadLabels();},onPreview:previewSound});showOrbitPanel=setupPhoneUI({showPage:showTab,currentPage:()=>activeTab});setupOrbitPads();setupSharedAdjuster();loadDemo('glass');resetBalls();updateOrbitReadout();showTab(pageNames.includes(location.hash.slice(1))?location.hash.slice(1):activeTab);window.addEventListener('hashchange',()=>{if(pageNames.includes(location.hash.slice(1)))showTab(location.hash.slice(1));});requestAnimationFrame(frame);
